</main><script>
const url=@json(route('elasticsearch-monitoring.api-requests.data',['locale'=>$locale])),labels=@json($t);
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const fmt=v=>v===null||v===undefined?'—':Number(v).toLocaleString(document.documentElement.lang,{maximumFractionDigits:2});
async function load(){const notice=document.getElementById('notice');try{const response=await fetch(url,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('HTTP '+response.status);const data=await response.json(),s=data.summary;
document.getElementById('total').textContent=fmt(s.total);document.getElementById('success').textContent=fmt(s.successful);document.getElementById('failed').textContent=fmt(s.failed);document.getElementById('average').textContent=fmt(s.average_ms);
const row=(item,slow=false)=>'<tr><td class="endpoint">'+esc(item.endpoint)+'</td><td>'+fmt(slow?item.average_ms:item.request_count)+'</td>'+(slow?'<td>'+fmt(item.request_count)+'</td>':'<td>'+fmt(item.average_ms)+'</td><td>'+fmt(item.max_ms)+'</td>')+'</tr>';
document.getElementById('top').innerHTML=(data.top_endpoints||[]).map(x=>row(x)).join('')||'<tr><td colspan="4">—</td></tr>';
document.getElementById('slow').innerHTML=(data.slowest_endpoints||[]).map(x=>row(x,true)).join('')||'<tr><td colspan="3">—</td></tr>';
document.getElementById('logs').innerHTML=(data.logs||[]).map(x=>'<tr><td>'+esc(x.method)+'</td><td class="endpoint">'+esc(x.endpoint)+'</td><td>'+fmt(x.status_code)+'</td><td>'+fmt(x.duration_ms)+'</td><td><span class="badge '+(x.successful?'text-bg-success':'text-bg-danger')+'">'+(x.successful?labels.ok:labels.error)+'</span>'+(x.error?'<div class="small text-danger text-wrap">'+esc(x.error)+'</div>':'')+'</td><td>'+esc(x.created_at?new Date(x.created_at).toLocaleString(document.documentElement.lang):'—')+'</td></tr>').join('')||'<tr><td colspan="6" class="text-center py-4 text-secondary">'+labels.empty+'</td></tr>';
document.getElementById('count').textContent=(data.meta.returned||0)+' / '+(data.meta.limit||500);notice.classList.add('d-none');
}catch(error){notice.textContent=error.message;notice.classList.remove('d-none')}}
document.getElementById('refresh').addEventListener('click',load);load();setInterval(load,30000);
</script></body></html>
